#!/usr/bin/env node
// Host-conformance fixture: REQUEST-side positive control (§2, §2.1).
// Unlike the other fixtures, this verifier does not misbehave; it inspects the
// bytes the host wrote and returns `allow` only if the host's request was
// conformant. Non-conformant requests get `deny code=malformed_input`, so a
// host that violates its own §2 MUSTs FAILS a vector whose expected decision
// is `allow`.
//
// Checks (each cites the spec clause it enforces):
//   §2   exactly one JSON object, UTF-8, then EOF; no second object, no
//        trailing non-whitespace bytes, no stream of objects. A host that
//        never closes stdin never reaches 'end' here, so it observes its own
//        timeout instead of `allow`.
//   §2.1 `now_unix` is REQUIRED and a positive integer: a JSON number that is
//        an integer after parse and > 0. `1.0e9` parses to an integer and is
//        accepted (JSON has one number type); `1700000000.5` and the string
//        "1700000000" are rejected.
//   §2.1 `granted_capabilities` is REQUIRED and an array of strings; an empty
//        array is permitted.
// Trailing whitespace (e.g. one newline after the object) is tolerated; the
// intent of §2 is to forbid extra data, and JSON.parse already rejects any
// second object or non-whitespace tail.
const chunks = [];
process.stdin.on('data', (c) => chunks.push(c));
process.stdin.on('error', () => finish(false));
process.stdin.on('end', () => {
  let ok = false;
  try {
    const raw = Buffer.concat(chunks).toString('utf8');
    if (raw.trim().length === 0) throw new Error('empty stdin');
    // JSON.parse throws on a second object, a stream of objects, or any
    // trailing non-whitespace bytes (§2).
    const req = JSON.parse(raw);
    if (req === null || typeof req !== 'object' || Array.isArray(req)) {
      throw new Error('request is not a single JSON object');
    }
    const now = req.now_unix;
    if (typeof now !== 'number' || !Number.isInteger(now) || now <= 0) {
      throw new Error('now_unix must be a positive integer (§2.1)');
    }
    const caps = req.granted_capabilities;
    if (!Array.isArray(caps) || !caps.every((c) => typeof c === 'string')) {
      throw new Error('granted_capabilities must be an array of strings (§2.1)');
    }
    ok = true;
  } catch (_e) {
    ok = false;
  }
  finish(ok);
});
process.stdin.resume();

function finish(ok) {
  const verdict = ok
    ? { verdict: 'allow' }
    : { verdict: 'deny', code: 'malformed_input' };
  process.stdout.write(JSON.stringify(verdict), () => process.exit(0));
}
